            tokens.append((_OP, two))
            i += 2
            continue

        if ch in "+-*/%(),":
            tokens.append((_OP, ch))
            i += 1
            continue

        raise CalcError("unexpected token %r" % ch)

    tokens.append((_EOF, None))
    return tokens


